import { App, Chart } from 'cdk8s';
import { KubeDeployment, KubeService } from './imports/k8s';
class Web extends Chart {
  constructor(scope: App, id: string) {
    super(scope, id);
    const labels = { app: 'web' };
    new KubeDeployment(this, 'dep', { spec: { replicas: 2, selector: { matchLabels: labels },
      template: { metadata: { labels }, spec: { containers: [{ name: 'web', image: 'nginx:1.27' }] } } } });
    new KubeService(this, 'svc', { spec: { selector: labels, ports: [{ port: 80 }] } });
  }
}
const app = new App(); new Web(app, 'web'); app.synth();

import * as kplus from 'cdk8s-plus-30';
export class StandardService extends Construct {
  constructor(scope: Construct, id: string, p: { image: string; port: number; replicas?: number }) {
    super(scope, id);
    const d = new kplus.Deployment(this, 'd', { replicas: p.replicas ?? 2 });
    d.addContainer({ image: p.image, portNumber: p.port,
      readiness: kplus.Probe.fromHttpGet('/healthz'),
      resources: { cpu: { request: kplus.Cpu.millis(100) }, memory: { request: Size.mebibytes(128) } } });
    d.exposeViaService({ ports: [{ port: 80, targetPort: p.port }] });
  }
}
